.rr-wt { background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px; }
.rr-wt-head { display: flex; align-items: center; gap: 10px; }
.rr-h2 { margin: 0; font-size: 15px; font-weight: 700; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-weak { color: #5c5c5c; }
.rr-small { font-size: 12px; }
.rr-wt-form { display: flex; flex-direction: column; gap: 10px; }
.rr-grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px; }
.rr-wt-actions { display: flex; gap: 8px; justify-content: flex-end; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; }
.rr-msg-bad { background: #fef1ee; color: #8e030f; }
.rr-msg-ok { background: #ebf7e6; color: #2e844a; }
